std::wstring wide(std::string_view s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),static_cast<int>(s.size()),nullptr,0);if(!n)throw CapabilityError("文字格式無法讀取。");std::wstring out(n,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),s.size(),out.data(),n);return out;}
std::string narrow(std::wstring_view s){if(s.empty())return {};int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),static_cast<int>(s.size()),nullptr,0,nullptr,nullptr);if(!n)throw CapabilityError("文字格式無法讀取。");std::string out(n,'\0');WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),s.size(),out.data(),n,nullptr,nullptr);return out;}
static std::wstring quote(const std::wstring&s){std::wstring out=L"\"";size_t slashes=0;for(wchar_t c:s){if(c==L'\\'){slashes++;continue;}if(c==L'\"'){out.append(slashes*2+1,L'\\');out+=c;}else{out.append(slashes,L'\\');out+=c;}slashes=0;}out.append(slashes*2,L'\\');return out+L"\"";}
// Transfer the embedded worker over the private pipe, not the process command line.
// PowerShell script-block logging may still record it; this is not a logging bypass.
Bridge::Bridge(){
 SECURITY_ATTRIBUTES security{sizeof security,nullptr,TRUE};
 HANDLE childRead=nullptr,childWrite=nullptr,error=nullptr;PROCESS_INFORMATION pi{};
 try{
  if(!CreatePipe(&childRead,&input,&security,0)||!CreatePipe(&output,&childWrite,&security,0))throw CapabilityError("無法啟動本機連線。");
  if(!SetHandleInformation(input,HANDLE_FLAG_INHERIT,0)||!SetHandleInformation(output,HANDLE_FLAG_INHERIT,0))throw CapabilityError("無法設定本機連線。");
  error=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_WRITE,&security,OPEN_EXISTING,0,nullptr);
  if(error==INVALID_HANDLE_VALUE)throw CapabilityError("無法啟動本機連線。");
  wchar_t dir[MAX_PATH];auto count=GetSystemDirectoryW(dir,MAX_PATH);
  if(!count||count>=MAX_PATH)throw CapabilityError("無法找到本機連線元件。");
  auto exe=fs::path(dir)/L"WindowsPowerShell/v1.0/powershell.exe";
  const std::wstring bootstrap=L"$ChatAtlasInput=[IO.StreamReader]::new([Console]::OpenStandardInput(),[Text.UTF8Encoding]::new($false,$true),$true);[Console]::SetIn($ChatAtlasInput);$worker=[Console]::ReadLine();& ([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($worker))))";
  std::wstring command=quote(exe.wstring())+L" -NoLogo -NoProfile -NonInteractive -Command "+quote(bootstrap);
  STARTUPINFOW si{};si.cb=sizeof si;si.dwFlags=STARTF_USESTDHANDLES;si.hStdInput=childRead;si.hStdOutput=childWrite;si.hStdError=error;
  if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW,nullptr,nullptr,&si,&pi))throw CapabilityError("無法啟動本機連線，請查看 Windows 是否允許執行。");
  process=pi.hProcess;CloseHandle(pi.hThread);
  CloseHandle(childRead);childRead=nullptr;CloseHandle(childWrite);childWrite=nullptr;CloseHandle(error);error=nullptr;
  auto payload=base64(worker_script)+"\n";size_t offset=0;
  while(offset<payload.size()){DWORD written=0;auto remaining=static_cast<DWORD>(std::min<size_t>(payload.size()-offset,65536));
   if(!WriteFile(input,payload.data()+offset,remaining,&written,nullptr)||!written)throw CapabilityError("本機連線已停止。");
   offset+=written;
  }
 }catch(...){if(childRead)CloseHandle(childRead);if(childWrite)CloseHandle(childWrite);if(error&&error!=INVALID_HANDLE_VALUE)CloseHandle(error);close();throw;}
}
Bridge::~Bridge(){close();}void Bridge::close(){if(process){TerminateProcess(process,0);WaitForSingleObject(process,2000);CloseHandle(process);process=nullptr;}if(input){CloseHandle(input);input=nullptr;}if(output){CloseHandle(output);output=nullptr;}}
J Bridge::call(std::string action,J values,Control*control){if(!process)throw CapabilityError("連線已停止，請重新連接 LINE。");values["action"]=action;auto line=values.dump(-1,' ',true)+"\n";try{BridgeRequestGate gate([&]{if(control)control->check();},[&]{if(control&&control->stopped.load())throw Cancelled();});gate.beforeSend();DWORD written=0;if(!WriteFile(input,line.data(),static_cast<DWORD>(line.size()),&written,nullptr)||written!=line.size())throw CapabilityError("本機連線已停止。");gate.afterSend();while(buffered.find('\n')==std::string::npos){if(!gate.withinDeadline())throw CapabilityError("LINE 回應逾時，已停止連線。");DWORD available=0;if(!PeekNamedPipe(output,nullptr,0,nullptr,&available,nullptr))throw CapabilityError("本機連線已停止。");if(available){char buffer[65536];DWORD count=0;if(!ReadFile(output,buffer,std::min<DWORD>(available,sizeof buffer),&count,nullptr)||!count)throw CapabilityError("本機連線已停止。");buffered.append(buffer,count);if(buffered.size()>16*1024*1024)throw CapabilityError("LINE 顯示的內容過多，請縮小範圍。");}else{if(WaitForSingleObject(process,0)==WAIT_OBJECT_0)throw CapabilityError("本機連線無法啟動。");std::this_thread::sleep_for(std::chrono::milliseconds(20));}}auto end=buffered.find('\n');auto result=J::parse(buffered.substr(0,end));buffered.erase(0,end+1);if(!result.value("ok",false)){auto code=result.value("code","");if(code=="focus_changed")throw CapabilityError("畫面已切換，請切回 LINE 後重新連接。");if(code=="publisher_unverified")throw CapabilityError("無法核對 LINE 的發行者，已停止連線。");if(code=="line_window_ambiguous")throw CapabilityError("請保留一個已登入的 LINE 主視窗，再重試。");if(code=="save_conflict_cleanup_required")throw CapabilityError("未接受覆寫；請手動取消 LINE 的保存視窗，再重新連接。");if(code=="save_conflict")throw CapabilityError("保存位置出現同名檔案，已取消覆寫，請重新連接。");if(code=="save_incomplete")throw CapabilityError("附件保存尚未完成，請確認 LINE 的保存視窗後重新連接。");if(code=="save_dialog_missing"||code=="save_dialog_unsupported")throw CapabilityError("LINE 的保存畫面目前無法辨識。");throw CapabilityError("目前無法安全讀取 LINE，請重新連接。");}gate.afterResponse();return result.value("result",J(nullptr));}catch(...){close();throw;}}
static std::string value(const J&j,const std::string&k,const std::string&fallback=""){return j.contains(k)&&j[k].is_string()?j[k].get<std::string>():fallback;}
static void selector(const J&s){if(!s.is_object()||s.empty())throw CapabilityError("連線設定不完整。");for(auto it=s.begin();it!=s.end();++it)if(!std::set<std::string>{"automation_id","name","control_type"}.count(it.key())||!it.value().is_string()||it.value().get_ref<const std::string&>().empty()||it.value().get_ref<const std::string&>().size()>1024)throw CapabilityError("連線設定不正確。");}
static void fieldConfig(const J&v,bool identity=false){if(v.is_string()&&!identity)return;if(!v.is_object())throw CapabilityError("內容辨識設定不完整。");for(auto it=v.begin();it!=v.end();++it)if(!std::set<std::string>{"selector","property","prefix","suffix","line"}.count(it.key()))throw CapabilityError("連線設定含不支援的欄位。");if(v.contains("selector"))selector(v["selector"]);if(!std::set<std::string>{"name","text","automation_id"}.count(value(v,"property","name")))throw CapabilityError("來源識別無法確認。");for(auto k:{"prefix","suffix"})if(v.contains(k)&&!v[k].is_string())throw CapabilityError("內容辨識格式不正確。");if(v.contains("line")&&(!v["line"].is_number_integer()||v["line"].get<int>()<0||v["line"].get<int>()>4096))throw CapabilityError("內容辨識格式不正確。");}
J WindowsSource::validate(J p){if(p.is_object()&&p.contains("process_name"))throw CapabilityError("LINE 程序不能由連線設定覆寫。");if(!p.is_object()||p.value("schema",0)!=1)throw CapabilityError("本機連線設定格式不相容。");for(auto k:{"account","chats","panels"})if(!p.contains(k)||!p[k].is_object())throw CapabilityError("本機連線設定不完整。");selector(p["account"].value("selector",J()));if(value(p["account"],"local_id").starts_with("synthetic-"))throw CapabilityError("連線設定使用了保留的範例識別，請重新核對。");if(value(p["account"],"local_id").empty()||value(p["account"],"expected_value").empty())throw CapabilityError("連線設定缺少帳號核對。");auto&c=p["chats"];for(auto k:{"container","row","selected_title"})selector(c.value(k,J()));fieldConfig(c.value("id",J()),true);fieldConfig(c.value("title",J()));fieldConfig(c.value("selected_id",J()),true);if(!c["selected_id"].contains("selector"))throw CapabilityError("連線設定缺少目前聊天室核對。");if(c.contains("parent_source_id"))fieldConfig(c["parent_source_id"],true);if(p["panels"].size()!=6)throw CapabilityError("連線設定尚未涵蓋全部內容。");for(auto it=p["panels"].begin();it!=p["panels"].end();++it){if(!allKinds.count(it.key())||!it.value().is_object())throw CapabilityError("來源內容類型不正確。");auto&panel=it.value();selector(panel.value("container",J()));selector(panel.value("row",J()));for(auto k:{"open","close"})if(panel.contains(k))selector(panel[k]);if(!panel.contains("fields")||!panel["fields"].is_object()||!panel["fields"].contains("source_id"))throw CapabilityError("來源缺少穩定識別。");fieldConfig(panel["fields"]["source_id"],true);for(auto f=panel["fields"].begin();f!=panel["fields"].end();++f){if(!std::set<std::string>{"source_id","text","sender_id","sender_name","sent_at","title","parent_source_id","reply_source_id","state","ordinal"}.count(f.key()))throw CapabilityError("內容欄位不相容。");fieldConfig(f.value(),std::set<std::string>{"source_id","sender_id","parent_source_id","reply_source_id"}.count(f.key()));}if((it.key()=="album_item"||it.key()=="comment")&&!panel["fields"].contains("parent_source_id"))throw CapabilityError("圖片或留言缺少所屬來源。");if(panel.contains("max_scrolls")&&(!panel["max_scrolls"].is_number_integer()||panel["max_scrolls"].get<int>()<1||panel["max_scrolls"].get<int>()>1000))throw CapabilityError("來源範圍設定不正確。");if(panel.contains("scroll")&&!panel["scroll"].is_boolean())throw CapabilityError("來源範圍設定不正確。");if(panel.contains("attachments"))for(auto&m:panel["attachments"]){selector(m.value("row",J()));selector(m.value("save_button",J()));if(!m.contains("fields")||!m["fields"].is_object()||!m["fields"].contains("source_id")||!m["fields"].contains("name"))throw CapabilityError("附件來源設定不完整。");for(auto f=m["fields"].begin();f!=m["fields"].end();++f){if(!std::set<std::string>{"source_id","name","kind","variant","version","expected_size","expected_sha256"}.count(f.key()))throw CapabilityError("附件欄位不相容。");fieldConfig(f.value(),std::set<std::string>{"source_id","version","expected_size","expected_sha256"}.count(f.key()));}}}return p;}
WindowsSource::WindowsSource(J p,Control* control):profile(validate(p)){Control local;RequestControlScope scope(requestControl,control?*control:local);request("connect");account=value(profile["account"],"local_id");assertAccount();}
J WindowsSource::find(const J&sel,const std::string&root){selector(sel);auto result=request("find",{{"selector",sel},{"root",root.empty()?J(nullptr):J(root)}});if(result.is_null())return J::array();return result.is_array()?result:J::array({result});}J WindowsSource::single(J nodes){if(nodes.size()!=1)throw CapabilityError("無法唯一辨識這個來源，已停止。");return nodes[0];}
std::string WindowsSource::field(const J&node,const J&config){if(config.is_string())return config.get<std::string>();fieldConfig(config);auto n=config.contains("selector")?single(find(config["selector"],value(node,"token"))):node;auto prop=value(config,"property","name");auto s=prop=="text"?request("text",{{"token",n["token"]}}).get<std::string>():value(n,prop);if(s.size()>262144)throw CapabilityError("來源欄位過長，未更新。");auto prefix=value(config,"prefix"),suffix=value(config,"suffix");if(!prefix.empty()){if(!s.starts_with(prefix))throw CapabilityError("來源內容格式改變，已停止。");s.erase(0,prefix.size());}if(!suffix.empty()){if(!s.ends_with(suffix))throw CapabilityError("來源內容格式改變，已停止。");s.resize(s.size()-suffix.size());}if(config.contains("line")){std::istringstream input(s);std::string line;int number=config["line"].get<int>();for(int i=0;i<=number;i++)if(!std::getline(input,line))throw CapabilityError("來源欄位不完整。");if(!line.empty()&&line.back()=='\r')line.pop_back();s=line;}return s;}
void WindowsSource::assertAccount(){auto&a=profile["account"];auto n=single(find(a["selector"]));if(request("text",{{"token",n["token"]}})!=a["expected_value"])throw CapabilityError("LINE 帳號或畫面改變，已停止。");}
void WindowsSource::assertChat(const J&c){assertAccount();auto n=single(find(profile["chats"]["selected_title"]));if(request("text",{{"token",n["token"]}})!=c["title"])throw CapabilityError("目前不是選取的聊天室，已停止。");auto config=profile["chats"]["selected_id"];n=single(find(config["selector"]));config.erase("selector");if(field(n,config)!=value(c,"source_id"))throw CapabilityError("聊天室識別改變，已停止。");}
J WindowsSource::chatsWithControl(Control& control){RequestControlScope scope(requestControl,control);control.check();auto result=chats();control.check();return result;}
J WindowsSource::chats(){assertAccount();auto&c=profile["chats"];auto container=single(find(c["container"]));J list=J::array();std::set<std::string>ids;for(auto&r:find(c["row"],value(container,"token"))){J item={{"source_id",field(r,c["id"])},{"title",field(r,c["title"])},{"kind",c.contains("kind")?field(r,c["kind"]):"group"}};if(c.contains("parent_source_id")){auto p=field(r,c["parent_source_id"]);if(!p.empty())item["parent_source_id"]=p;}validateChat(item);auto id=value(item,"source_id");if(!ids.insert(id).second)throw CapabilityError("聊天室來源識別重複，尚未採集。");tokens[id]=value(r,"token");list.push_back(item);}return list;}
void WindowsSource::select(const J&c,Control&control){auto all=chats();auto match=std::count_if(all.begin(),all.end(),[&](const J&v){return v["source_id"]==c["source_id"]&&v["title"]==c["title"];});if(match!=1)throw CapabilityError("選取的聊天室已改變，請重新選擇。");request("activate",J::object());request("select",{{"token",tokens[value(c,"source_id")]}});for(int i=0;;i++){try{assertChat(c);return;}catch(const Cancelled&){throw;}catch(...){if(i>=50)throw;control.wait(100);}}}
void WindowsSource::panel(const J&config,bool open,Control&c){auto key=open?"open":"close";if(config.contains(key)){auto n=single(find(config[key]));request("invoke_navigation",{{"token",n["token"]}});c.wait(120);}}
Batch WindowsSource::read(const J&chat,const std::set<std::string>&kinds,const std::string&since,const std::string&until,Control&control){RequestControlScope scope(requestControl,control);select(chat,control);std::map<std::string,J>seen,attachments;for(const auto&kind:std::vector<std::string>{"message","album","album_item","note","comment","thread"}){auto config=profile["panels"][kind];if(!kinds.count(kind))continue;if(config.contains("chat_kinds")&&std::find(config["chat_kinds"].begin(),config["chat_kinds"].end(),chat["kind"])==config["chat_kinds"].end())continue;control.check();assertChat(chat);panel(config,true,control);auto container=single(find(config["container"]));int unchanged=0;for(int turn=0;turn<config.value("max_scrolls",200);turn++){control.check();assertChat(chat);auto before=seen.size();for(auto&row:find(config["row"],value(container,"token"))){assertChat(chat);J item;for(auto f=config["fields"].begin();f!=config["fields"].end();++f)item[f.key()]=field(row,f.value());auto id=value(item,"source_id");if(item.contains("ordinal"))item["ordinal"]=std::stoll(value(item,"ordinal"));else item["ordinal"]=seen.count(id)?seen[id]["ordinal"]:J(seen.size());item["kind"]=kind;validateItem(item);if(seen.count(id)&&seen[id]!=item)throw CapabilityError("來源內容在讀取期間改變，未覆寫舊資料。");seen[id]=item;if(config.contains("attachments"))for(auto&m:config["attachments"])for(auto&candidate:find(m["row"],value(row,"token"))){J a;for(auto f=m["fields"].begin();f!=m["fields"].end();++f)a[f.key()]=field(candidate,f.value());a["item_source_id"]=id;if(a.contains("expected_size"))a["expected_size"]=std::stoll(value(a,"expected_size"));validateAttachment(a);auto aid=key({value(chat,"source_id"),id,value(a,"source_id"),value(a,"variant"),value(a,"version")});if(attachments.count(aid)&&attachments[aid]!=a)throw CapabilityError("附件來源改變，已停止。");attachments[aid]=a;downloads[aid]={{"kind",kind},{"media",m}};}assertChat(chat);}unchanged=seen.size()==before?unchanged+1:0;if(unchanged>=2||!config.value("scroll",false)||!request("scroll_up",{{"token",container["token"]}}).get<bool>())break;control.wait(150);container=single(find(config["container"]));}panel(config,false,control);}std::set<std::string>keep;for(auto&[id,i]:seen){auto t=value(i,"sent_at");if(i["kind"]!="message"||t.empty()||((since.empty()||t>=since)&&(until.empty()||t<until)))keep.insert(id);}std::vector<std::string>queue(keep.begin(),keep.end());for(size_t at=0;at<queue.size();at++){auto p=value(seen[queue[at]],"parent_source_id");if(!p.empty()&&!keep.count(p)){if(!seen.count(p))throw CapabilityError("來源缺少上層內容，未建立孤立項目。");keep.insert(p);queue.push_back(p);}}Batch result;result.coverage="visible_only";for(auto&[id,item]:seen)if(keep.count(id))result.items.push_back(item);for(auto&[_,a]:attachments)if(keep.count(value(a,"item_source_id")))result.attachments.push_back(a);return result;}
fs::path WindowsSource::download(const J&chat,const J&a,const fs::path&dir,Control&control){RequestControlScope scope(requestControl,control);control.check();assertChat(chat);if(a["expected_size"].is_null()&&a["expected_sha256"].is_null())throw IntegrityError("來源缺少完整檔案資訊，未下載。");auto aid=key({value(chat,"source_id"),value(a,"item_source_id"),value(a,"source_id"),value(a,"variant"),value(a,"version")});if(!downloads.count(aid))throw CapabilityError("附件目前無法核對，請重新保存聊天室。");auto binding=downloads[aid],config=profile["panels"][value(binding,"kind")],media=binding["media"];select(chat,control);panel(config,true,control);auto container=single(find(config["container"]));if(config.value("scroll",false))for(int n=0;n<config.value("max_scrolls",200);n++){control.check();assertChat(chat);if(!request("scroll_up",{{"token",container["token"]}}).get<bool>())break;control.wait(150);container=single(find(config["container"]));}J save;for(int n=0;n<config.value("max_scrolls",200);n++){control.check();assertChat(chat);for(auto&row:find(config["row"],value(container,"token"))){if(field(row,config["fields"]["source_id"])!=value(a,"item_source_id"))continue;for(auto&candidate:find(media["row"],value(row,"token"))){J observed;for(auto f=media["fields"].begin();f!=media["fields"].end();++f)observed[f.key()]=field(candidate,f.value());observed["item_source_id"]=a["item_source_id"];if(observed.contains("expected_size"))observed["expected_size"]=std::stoll(value(observed,"expected_size"));validateAttachment(observed);bool same=true;for(auto k:{"source_id","variant","version","expected_size","expected_sha256"})if(observed[k]!=a[k])same=false;if(same)save=single(find(media["save_button"],value(candidate,"token")));}}if(!save.is_null()||!config.value("scroll",false)||!request("scroll_down",{{"token",container["token"]}}).get<bool>())break;control.wait(150);container=single(find(config["container"]));}if(save.is_null())throw CapabilityError("無法找到這份附件，未改下載其他檔案。");assertChat(chat);auto file=dir/"payload.bin";request("download",{{"token",save["token"]},{"destination",utf8(file)}});uint64_t previous=UINT64_MAX;int stable=0;for(int n=0;n<480;n++){control.check();if(fs::is_regular_file(file)){auto size=fs::file_size(file);stable=size==previous?stable+1:0;previous=size;if(stable>=4&&(a["expected_size"].is_null()||a["expected_size"]==size)){assertChat(chat);auto d=digest(file,[&]{control.check();});if(!a["expected_sha256"].is_null()&&d.hash!=value(a,"expected_sha256"))throw IntegrityError("附件內容不符，未列為完整副本。");try{panel(config,false,control);}catch(const Cancelled&){throw;}catch(...){}return file;}}control.wait(250);}throw CapabilityError("附件保存尚未完成，可稍後重試。");}
J probe(Control* control){if(control)control->check();Bridge bridge;auto info=bridge.call("connect",J::object(),control);auto shape=bridge.call("inspect",J::object(),control);return {{"version",info.value("version",J(""))},{"publisher_verified",info.value("publisher_verified",J(false))},{"capabilities",shape},{"integration_verified",false}};}
